example:
判别字段 + default 赋给 never，逼出未处理成员：

```ts
type Result =
  | { kind: "ok"; data: string }
  | { kind: "error"; message: string }
  // | { kind: "loading" }  // 新增后 default 会炸

function view(r: Result) {
  switch (r.kind) {
    case "ok": return r.data
    case "error": return r.message
    default: {
      const _exhaustive: never = r
      return _exhaustive
    }
  }
}
```
